import olympiad; size(150); defaultpen(linewidth(0.8));
xaxis(0,16,Ticks("%",1.0));
yaxis(0,8,Ticks("%",1.0));
filldraw(circle((4,4),4),gray(0.7));
filldraw((0,4)--(4,4)--(4,0)--(0,0)--cycle,fillpen=white);
filldraw((8,4)--(12,4)--(12,0)--(8,0)--cycle,gray(0.7));
dot("$A$",(4,4),S); dot("$B$",(12,4),S); dot("$D$",(0,4),S);
dot("$C$",(8,4),S);
label("(panel), here",(6,8),N);
[/asy] Second, we find the area of $\triangle{BCD}.$ This is simply $\frac{1}{2}(4)(8)=16.$ The area we want is the area of sector $ABD$ minus the area of $\triangle{BCD},$ so our final answer is $2\pi-16.$ </think> <answer> $2\pi-16$ </answer>

